CREATE FUNCTION [dbo].[Decrypt]
(
	@ValueToDecrypt Varchar(max)
)
RETURNS varchar(max)
AS 
BEGIN

	DECLARE @result varchar(max)

	SET @result = ISNULL(LTRIM(RTRIM(DECRYPTBYKEY(@ValueToDecrypt))), '')

	RETURN @result

END
GO

